insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-1061','5-54',1061,'形式','xíng shì','hình thức','他们采用了新的形式来解决问题。','Tāmen cǎiyòngle xīn de xíngshì lái jiějué wèntí.','Họ đã áp dụng hình thức mới để giải quyết vấn đề.');
