insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-1109','5-56',1109,'乙','yǐ','ất','乙是第二个字母。','Yǐ shì dì èr gè zìmǔ.','Y là chữ cái thứ hai.');
