insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-1113','5-56',1113,'义务','yì wù','nghĩa vụ','我们有义务保护环境。','Wǒmen yǒu yìwù bǎohù huánjìng.','Chúng ta có nghĩa vụ bảo vệ môi trường.');
