insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-100','6-5',100,'鼻涕','bí tì','nước mũi','小孩子经常流鼻涕。','xiǎo háizi jīngcháng liú bítì.','Trẻ con thường hay chảy nước mũi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-101','6-6',101,'比方','bǐ fāng','ví dụ','比方说，你可以这样做。','bǐfāng shuō, nǐ kěyǐ zhèyàng zuò.','Ví dụ như, bạn có thể làm thế này.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-102','6-6',102,'比喻','bǐ yù','so sánh, ví von','他用比喻的方式来解释这个概念。','tā yòng bǐyù de fāngshì lái jiěshì zhège gàiniàn.','Anh ấy dùng phép ẩn dụ để giải thích khái niệm này.');
