insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-105','6-6',105,'弊病','bì bìng','tệ nạn, bệnh tật','我们需要解决这个系统的弊病。','wǒmen xūyào jiějué zhège xìtǒng de bìbìng.','Chúng ta cần giải quyết các khuyết điểm của hệ thống này.');
