insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-107','6-6',107,'弊端','bì duān','tệ nạn, sai sót','这个政策存在很多弊端。','zhège zhèngcè cúnzài hěn duō bìduān.','Chính sách này có nhiều khuyết điểm.');
