insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-133','6-7',133,'飙升','biāo shēng','tăng vọt','房价在短时间内飙升了。','fángjià zài duǎn shíjiān nèi biāoshēng le.','Giá nhà đã tăng vọt trong thời gian ngắn.');
